class Solution:
    def maxVowels(self, s: str, k: int) -> int:
        vowels = "aeiou"
        v_count = 0
        v_max = 0

        for c in s[:k]:
            if c in vowels:
                v_count += 1
        
        v_max = max(v_max, v_count)

        for i in range(k, len(s)):
            if s[i] in vowels:
                v_count += 1
            if s[i - k] in vowels:
                v_count -= 1
            v_max = max(v_max, v_count)
                
        return v_max

class Solution:
