        nums1 = []
        nums2 = []
        same = []

        for i in range(len(nums)):
            if nums[i] < pivot:
                nums1.append(nums[i])
            elif nums[i] > pivot:
                nums2.append(nums[i])
            else:
                same.append(nums[i])
        
        nums1.extend(same)
        nums1.extend(nums2)
